// ===========================================================================
//  Intersection (public API — calls into orourke_cgal)
// ===========================================================================

inline void intersect(const Polygon& subject, const Polygon& clip,
                      std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    P_verts.reserve(subject.size());
    Q_verts.reserve(clip.size());
    for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
        P_verts.push_back(*it);
    }
    for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
        Q_verts.push_back(*it);
    }

    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

inline void intersect(const std::vector<Point>& P_verts, const std::vector<Point>& Q_verts,
                      std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

// ===========================================================================
//  Trajectory-simplification geometry helpers
// ===========================================================================

static constexpr double BMIN_geom = -10000;
static constexpr double BMAX_geom =  10000;
static constexpr double TOL_geom  = 1e-6;

inline bool point_in_convex(const Point& p, const std::vector<Point>& poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto& a = poly[i];
        const auto& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

inline std::optional<Point> ray_hit_bbox(const Point& p, const Point& dir) {
    double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    double dx = CGAL::to_double(dir.x()) - px,
           dy = CGAL::to_double(dir.y()) - py;
    double best = std::numeric_limits<double>::infinity(), hx = 0, hy = 0;
    auto consider = [&best, &hx, &hy, dx, dy, px, py](double t) {
        if (t <= 0) return;
        double x = px + t * dx, y = py + t * dy;
        if (x < BMIN_geom - 1e-8 || x > BMAX_geom + 1e-8 ||
            y < BMIN_geom - 1e-8 || y > BMAX_geom + 1e-8) return;
        if (t < best) { best = t; hx = x; hy = y; }
    };
    if (std::abs(dx) > 1e-18) {
        consider((BMIN_geom - px) / dx);
        consider((BMAX_geom - px) / dx);
    }
    if (std::abs(dy) > 1e-18) {
        consider((BMIN_geom - py) / dy);
        consider((BMAX_geom - py) / dy);
    }
    if (!std::isfinite(best)) return std::nullopt;
    return Point(hx, hy);
}

enum class Bbox_edge {
    BL = 0, BOTTOM = 1, BR = 2, RIGHT = 3,
    TR = 4, TOP = 5,    TL = 6, LEFT = 7
};

inline std::array<Point, 4> current_bbox_corner() {
    return {Point(BMIN_geom, BMIN_geom), Point(BMAX_geom, BMIN_geom),
            Point(BMAX_geom, BMAX_geom), Point(BMIN_geom, BMAX_geom)};
}

inline std::vector<Point> current_bbox() {
    auto c = current_bbox_corner();
    return std::vector<Point>(c.begin(), c.end());
}

inline std::optional<Bbox_edge> which_edge(const Point& s) {
    double x = CGAL::to_double(s.x()), y = CGAL::to_double(s.y());
    bool on_left   = std::abs(x - BMIN_geom) < TOL_geom;
    bool on_right  = std::abs(x - BMAX_geom) < TOL_geom;
    bool on_bottom = std::abs(y - BMIN_geom) < TOL_geom;
    bool on_top    = std::abs(y - BMAX_geom) < TOL_geom;

    if (on_left && on_bottom) return Bbox_edge::BL;
    if (on_right && on_bottom) return Bbox_edge::BR;
    if (on_right && on_top) return Bbox_edge::TR;
    if (on_left && on_top) return Bbox_edge::TL;
    if (on_bottom) return Bbox_edge::BOTTOM;
    if (on_right)  return Bbox_edge::RIGHT;
    if (on_top)    return Bbox_edge::TOP;
    if (on_left)   return Bbox_edge::LEFT;
    return std::nullopt;
}

inline void append_rect_pts(std::vector<Point>& out, Bbox_edge from, Bbox_edge to, bool ccw) {
    auto corners = current_bbox_corner();
    auto next = [&](int idx) { return (idx + (ccw ? 1 : 7)) % 8; };

    int i = static_cast<int>(from);
    int j = static_cast<int>(to);
    if (i == j) return;
    for (int k = next(i); k != j; k = next(k)) {
        if ((k & 1) == 0) {
            int ci = k / 2;
            out.push_back(corners[ci]);
        }
    }
}

template <class F>
inline void for_each_grid_row(double px, double py, double r, double GRID, F&& f) {
    const double r2 = r * r;
    const int y_min = -(r / GRID) - 1;
    const int y_max = -y_min;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const double dy2 = y_actual * y_actual;
        if (dy2 > r2) continue;
        const double dx = std::sqrt(r2 - dy2);
        const int x_min = static_cast<int>(-dx / GRID - 1);
        const int x_max = static_cast<int>(+dx / GRID + 1);
        f(px, py, y_actual, x_min, x_max);
    }
}

inline double GRID_val(double EPSILON, double DELTA) {
    return EPSILON * DELTA / (2 * std::sqrt(2));
}

inline double R_val(double EPSILON, double DELTA) {
    return (1.0 + EPSILON / 2.0) * DELTA;
}

inline double& expected_frechet_ref() {
    static double value = 0;
    return value;
}

inline std::vector<Point> get_points_from_grid(const Point& p, double EPSILON, double DELTA) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val(EPSILON, DELTA);
    if (DELTA == 0) return std::vector<Point>{p};

    const double r = R_val(EPSILON, DELTA);
    const double r2 = r * r;
    const double r2_eps = r2 * (1.0 + 1e-9);

    const int j_min = static_cast<int>(std::floor(-r / GRID)) - 1;
    const int j_max = static_cast<int>(std::ceil(r / GRID)) + 1;
    const int k_min = j_min;
    const int k_max = j_max;

    auto cell_stabs = [&](int j, int k) -> bool {
        double cx = (j + 0.5) * GRID;
        double cy = (k + 0.5) * GRID;
        return (cx * cx + cy * cy) <= r2_eps;
    };

    std::vector<Point> points;
    for (int j = j_min; j <= j_max; ++j) {
        for (int k = k_min; k <= k_max; ++k) {
            if (cell_stabs(j-1, k-1) || cell_stabs(j, k-1) ||
                cell_stabs(j-1, k) || cell_stabs(j, k)) {
                Point corner(px + j * GRID, py + k * GRID);
                points.push_back(corner);
                expected_frechet_ref() = std::max(expected_frechet_ref(),
                    CGAL::to_double(CGAL::squared_distance(p, corner)));
            }
        }
    }
    return points;
}

inline std::vector<Point> get_conv_from_grid(const Point& p, double EPSILON, double DELTA) {
    std::vector<Point> points = get_points_from_grid(p, EPSILON, DELTA);
    std::vector<Point> conv;
    CGAL::convex_hull_2(points.begin(), points.end(), std::back_inserter(conv));
    return conv;
}

inline std::vector<int> find_tangent_idx(const Point& p, const std::vector<Point>& S) {
    int n = S.size();
    std::vector<int> tangent;
    tangent.reserve(2);

    auto orient_at = [&](int i) {
        return CGAL::orientation(p, S[i], S[(i + 1) % n]);
    };

    int prev = orient_at(n - 1);
    for (int i = 0; i < n; ++i) {
        int cur = orient_at(i);
        if (cur != prev && cur != CGAL::COLLINEAR) {
            tangent.push_back(i);
            if (tangent.size() == 2) break;
        }
        prev = cur;
    }
    return tangent;
}

inline std::optional<Point> intersect_ray_with_rect(const Point& p, const Point& direction) {
    if (CGAL::to_double(CGAL::squared_distance(p, direction)) < TOL_geom * TOL_geom)
        return std::nullopt;

    Ray ray(p, direction);
    Bbox box(BMIN_geom, BMIN_geom, BMAX_geom, BMAX_geom);

    if (auto obj = CGAL::intersection(Rect(box), ray)) {
        if (const Point* ip = std::get_if<Point>(&*obj)) {
            if (CGAL::to_double(CGAL::squared_distance(*ip, p)) < TOL_geom * TOL_geom)
                return std::nullopt;
            return *ip;
        }
        if (const Segment* seg = std::get_if<Segment>(&*obj)) {
            const Point& a = seg->source();
            const Point& b = seg->target();
            double da = CGAL::to_double(CGAL::squared_distance(a, p));
            double db = CGAL::to_double(CGAL::squared_distance(b, p));
            if (da < TOL_geom * TOL_geom) return b;
            if (db < TOL_geom * TOL_geom) return a;
            return (da < db) ? a : b;
        }
    }
    return std::nullopt;
}

inline std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    assert(S.size() != 2);
    if (S.size() == 1) return current_bbox();
    if (point_in_convex(p, S)) return current_bbox();

    std::vector<int> tangent = find_tangent_idx(p, S);
    assert(tangent.size() == 2);

    auto hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
    auto hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    if (!hit1 || !hit2) {
        std::cerr << "Ray doesn't intersect with bounding box!\n";
        return current_bbox();
    }

    auto e1 = which_edge(hit1.value());
    auto e2 = which_edge(hit2.value());

    int n = int(S.size());
    assert(n >= 3);
    CGAL_precondition(Polygon(S.begin(), S.end()).is_counterclockwise_oriented());
    assert(tangent[1] - tangent[0] - 1 >= 1 || tangent[0] + n - tangent[1] - 1 >= 1);

    std::vector<Point> F;
    if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]])) {
        std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1, std::back_inserter(F));
        F.push_back(hit2.value());
        append_rect_pts(F, e2.value(), e1.value(), true);
        F.push_back(hit1.value());
    } else {
        std::copy(S.begin() + tangent[1], S.end(), std::back_inserter(F));
        std::copy(S.begin(), S.begin() + tangent[0] + 1, std::back_inserter(F));
        F.push_back(hit1.value());
        append_rect_pts(F, e1.value(), e2.value(), true);
        F.push_back(hit2.value());
    }

    if (!e1 || !e2) {
        std::cerr << "Cannot determine which Bbox edge the ray intersect with.\n";
        return current_bbox();
    }
    return F;
}

#endif // SIMPLIFY_GEOMETRY_H

