#ifndef SIMPLIFY_GEOMETRY_H
#define SIMPLIFY_GEOMETRY_H

#include <CGAL/Cartesian_converter.h>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Polygon_with_holes_2.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/intersections.h>

#include <optional>
#include <vector>

using Epick = CGAL::Exact_predicates_inexact_constructions_kernel;
using Epeck = CGAL::Exact_predicates_exact_constructions_kernel;

static inline CGAL::Cartesian_converter<Epick, Epeck> conv_to_exact;
static inline CGAL::Cartesian_converter<Epeck, Epick> conv_to_inexact;

using Kernel = Epick;
using Point  = Kernel::Point_2;
using Vector = Kernel::Vector_2;
using Segment = Kernel::Segment_2;
using Ray    = Kernel::Ray_2;
using Line   = Kernel::Line_2;
using Bbox   = CGAL::Bbox_2;
using Rect   = CGAL::Iso_rectangle_2<Kernel>;

using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

// ===========================================================================
//  Helpers
// ===========================================================================

inline double kernel_signed_area(const std::vector<Point>& P) {
    double s = 0.0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// ===========================================================================
//  O'Rourke's ConvexIntersect (Ch. 7, "Computational Geometry in C", 2nd ed.)
// ===========================================================================
namespace orourke_cgal {

enum class InFlag { Pin, Qin, Unknown };

inline int area_sign(const Point& a, const Point& b, const Point& c) {
    switch (CGAL::orientation(a, b, c)) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        case CGAL::COLLINEAR:  return  0;
    }
    return 0;
}

inline int area_sign_vec(const Vector& a, const Vector& b) {
    auto c = CGAL::determinant(a, b);
    if (c > 0) return  1;
    if (c < 0) return -1;
    return 0;
}

inline bool between(const Point& a, const Point& b, const Point& c) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return false;
    if (CGAL::abs(b.x() - a.x()) >= CGAL::abs(b.y() - a.y())) {
        return (a.x() <= c.x() && c.x() <= b.x()) ||
               (a.x() >= c.x() && c.x() >= b.x());
    }
    return (a.y() <= c.y() && c.y() <= b.y()) ||
           (a.y() >= c.y() && c.y() >= b.y());
}

inline int dot_sign(const Point& a, const Point& b,
                    const Point& c, const Point& d) {
    auto ux = b.x() - a.x(), uy = b.y() - a.y();
    auto vx = d.x() - c.x(), vy = d.y() - c.y();
    auto s  = ux * vx + uy * vy;
    if (s > 0) return  1;
    if (s < 0) return -1;
    return 0;
}

inline char parallel_int(const Point& a, const Point& b,
                         const Point& c, const Point& d,
                         Point& out_p, Point& out_q) {
    if (CGAL::orientation(a, b, c) != CGAL::COLLINEAR) return '0';

    if (between(a, b, c) && between(a, b, d)) { out_p = c; out_q = d; return 'e'; }
    if (between(c, d, a) && between(c, d, b)) { out_p = a; out_q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, b)) { out_p = c; out_q = b; return 'e'; }
    if (between(a, b, c) && between(c, d, a)) { out_p = c; out_q = a; return 'e'; }
    if (between(a, b, d) && between(c, d, b)) { out_p = d; out_q = b; return 'e'; }
    if (between(a, b, d) && between(c, d, a)) { out_p = d; out_q = a; return 'e'; }
    return '0';
}

inline Point line_point(const Point& a, const Point& b,
                        const Point& c, const Point& d) {
    double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
    double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
    double cx = CGAL::to_double(c.x()), cy = CGAL::to_double(c.y());
    double dx = CGAL::to_double(d.x()), dy = CGAL::to_double(d.y());
    double rx = bx - ax, ry = by - ay;
    double sx = dx - cx, sy = dy - cy;
    double denom = rx * sy - ry * sx;
    double t = ((cx - ax) * sy - (cy - ay) * sx) / denom;
    return Point(ax + t * rx, ay + t * ry);
}

inline char seg_seg_int(const Point& a, const Point& b,
                        const Point& c, const Point& d,
                        Point& p, Point& q) {
    int d1 = area_sign(c, d, a);
    int d2 = area_sign(c, d, b);
    int d3 = area_sign(a, b, c);
    int d4 = area_sign(a, b, d);

    if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
        ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
        p = line_point(a, b, c, d);
        return '1';
    }

    if (d1 == 0 && d2 == 0 && d3 == 0 && d4 == 0) {
        return parallel_int(a, b, c, d, p, q);
    }

    if (d1 == 0 && between(c, d, a)) { p = a; return 'v'; }
    if (d2 == 0 && between(c, d, b)) { p = b; return 'v'; }
    if (d3 == 0 && between(a, b, c)) { p = c; return 'v'; }
    if (d4 == 0 && between(a, b, d)) { p = d; return 'v'; }
    return '0';
}

inline int advance(int a, int& aa, int n, bool inside,
                   const Point& v, std::vector<Point>& out) {
    if (inside) out.push_back(v);
    aa++;
    return (a + 1) % n;
}

inline InFlag in_out(const Point& /*p*/, InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    return inflag;
}

inline bool point_in_convex_poly(const Point& p, const std::vector<Point>& poly) {
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == CGAL::RIGHT_TURN) return false;
    }
    return true;
}

inline bool all_points_in_convex_poly(const std::vector<Point>& inner,
                                      const std::vector<Point>& outer) {
    for (const auto& v : inner) {
        if (!point_in_convex_poly(v, outer)) return false;
    }
    return true;
}

inline std::optional<Point> line_intersect(const Point& a, const Point& b,
                                           const Point& p1, const Point& p2) {
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN) ? std::optional<Point>(p1) : std::nullopt;
    }

    Epeck::Point_2 ae = conv_to_exact(a);
    Epeck::Point_2 be = conv_to_exact(b);
    Epeck::Point_2 p1e = conv_to_exact(p1);
    Epeck::Point_2 p2e = conv_to_exact(p2);

    Epeck::Segment_2 seg_ab(ae, be);
    Epeck::Segment_2 seg_p(p1e, p2e);
    auto inter = CGAL::intersection(seg_ab, seg_p);
    if (!inter) return std::nullopt;
    if (const Epeck::Point_2* ip = std::get_if<Epeck::Point_2>(&*inter)) {
        return conv_to_inexact(*ip);
    }
    return std::nullopt;
}

inline std::vector<Point> clip_halfplane(const std::vector<Point>& subject,
                                          const Point& a, const Point& b) {
    int n = (int)subject.size();
    if (n == 0) return {};

    Epeck::Point_2 ae = conv_to_exact(a);
    Epeck::Point_2 be = conv_to_exact(b);

    std::vector<Point> out;
    out.reserve(n + 1);

    for (int i = 0; i < n; ++i) {
        const Point& cur  = subject[i];
        const Point& prev = subject[(i + n - 1) % n];
        auto o_cur  = CGAL::orientation(ae, be, conv_to_exact(cur));
        auto o_prev = CGAL::orientation(ae, be, conv_to_exact(prev));
        bool cur_in  = (o_cur  != CGAL::RIGHT_TURN);
        bool prev_in = (o_prev != CGAL::RIGHT_TURN);

        if (cur_in) {
            if (!prev_in) {
                if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
            }
            out.push_back(cur);
        } else if (prev_in) {
            if (auto ip = line_intersect(a, b, prev, cur)) out.push_back(*ip);
        }
    }
    return out;
}

inline std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    auto signed_area_sign = [](const std::vector<Point>& P) {
        Epeck::FT s = 0;
        int sz = (int)P.size();
        for (int i = 0; i < sz; ++i) {
            Epeck::Point_2 a = conv_to_exact(P[i]);
            Epeck::Point_2 b = conv_to_exact(P[(i + 1) % sz]);
            s += a.x() * b.y() - b.x() * a.y();
        }
        return CGAL::sign(s);
    };

    std::vector<Point> P, Q;
    P.reserve(Pin.size());
    Q.reserve(Qin.size());
    if (signed_area_sign(Pin) < 0) { P.assign(Pin.rbegin(), Pin.rend()); }
    else                            { P = Pin; }
    if (signed_area_sign(Qin) < 0) { Q.assign(Qin.rbegin(), Qin.rend()); }
    else                            { Q = Qin; }

    if (point_in_convex_poly(P[0], Q) && all_points_in_convex_poly(P, Q)) return P;
    if (point_in_convex_poly(Q[0], P) && all_points_in_convex_poly(Q, P)) return Q;

    std::vector<Point> running = P;
    int m = (int)Q.size();
    for (int i = 0; i < m; ++i) {
        const Point& a = Q[i];
        const Point& b = Q[(i + 1) % m];
        running = clip_halfplane(running, a, b);
        if (running.size() < 3) return {};
    }
    return running;
}

inline std::vector<Point> convex_intersect(const std::vector<Point>& Pin,
                                           const std::vector<Point>& Qin) {
    int n = (int)Pin.size();
    int m = (int)Qin.size();
    if (n < 3 || m < 3) return {};

    auto signed_area = [](const std::vector<Point>& P) {
        return kernel_signed_area(P);
    };
    auto leftmost_index = [](const std::vector<Point>& P) {
        int best = 0;
        for (int i = 1; i < (int)P.size(); ++i) {
            if (CGAL::compare_y(P[i], P[best]) == CGAL::SMALLER ||
                (CGAL::compare_y(P[i], P[best]) == CGAL::EQUAL &&
                 CGAL::compare_x(P[i], P[best]) == CGAL::SMALLER)) {
                best = i;
            }
        }
        return best;
    };
    std::vector<Point> Pr, Qr;
    int a, b;
    Pr = Pin;
    Qr = Qin;
    if (signed_area(Pr) < 0) std::reverse(Pr.begin(), Pr.end());
    if (signed_area(Qr) < 0) std::reverse(Qr.begin(), Qr.end());
    a = leftmost_index(Pr);
    b = leftmost_index(Qr);

    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;
    Point p0;

    std::vector<Point> out;

    do {
        int a1 = (a + n - 1) % n;
        int b1 = (b + m - 1) % m;

        Vector A = Pr[a] - Pr[a1];
        Vector B = Qr[b] - Qr[b1];

        int cross  = area_sign_vec(A, B);
        int aHB    = area_sign(Qr[b1], Qr[b], Pr[a]);
        int bHA    = area_sign(Pr[a1], Pr[a], Qr[b]);

        Point p, q;
        char code = seg_seg_int(Pr[a1], Pr[a], Qr[b1], Qr[b], p, q);

        if (code == '1' || code == 'v') {
            if (inflag == InFlag::Unknown && first_point) {
                aa = ba = 0;
                first_point = false;
                p0 = p;
            }
            out.push_back(p);
            inflag = in_out(p, inflag, aHB, bHA);
        }

        if ((code == 'e') && (dot_sign(Pr[a1], Pr[a], Qr[b1], Qr[b]) < 0)) {
            out.push_back(p);
            out.push_back(q);
            return out;
        }

        if ((cross == 0) && (aHB < 0) && (bHA < 0)) {
            return {};
        }

        if ((cross == 0) && (aHB == 0) && (bHA == 0)) {
            if (inflag == InFlag::Pin)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        } else if (cross >= 0) {
            if (bHA > 0)
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
            else
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
        } else {
            if (aHB > 0)
                b = advance(b, ba, m, inflag == InFlag::Qin, Qr[b], out);
            else
                a = advance(a, aa, n, inflag == InFlag::Pin, Pr[a], out);
        }
    } while (((aa < n) || (ba < m)) && (aa < 2 * n) && (ba < 2 * m));

    if (first_point) {
        if (point_in_convex_poly(Pr[0], Qr)) return Pr;
        if (point_in_convex_poly(Qr[0], Pr)) return Qr;
        return {};
    }

    out.push_back(p0);
    return out;
}

}  // namespace orourke_cgal

// ===========================================================================
//  Intersection (public API — calls into orourke_cgal)
// ===========================================================================

inline void intersect(const Polygon& subject, const Polygon& clip,
                      std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    P_verts.reserve(subject.size());
    Q_verts.reserve(clip.size());
    for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
        P_verts.push_back(*it);
    }
    for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
        Q_verts.push_back(*it);
    }

    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

inline void intersect(const std::vector<Point>& P_verts, const std::vector<Point>& Q_verts,
                      std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    Polygon inter_poly(verts.begin(), verts.end());
    if (!inter_poly.is_simple()) return;
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

#endif // SIMPLIFY_GEOMETRY_H

#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/Iso_rectangle_2.h>
#include <array>
#include <cmath>
#include <cstring>
#include <fstream>
#include <iostream>
#include <filesystem>
#include <limits>
#include <string>
#include <vector>
#include <QApplication>
#include "drawing.h"
#include "simplify_geometry.h"
#include "timer.h"

// ===========================================================================
//  Global parameters
// ===========================================================================

double DELTA = 200;
double EPSILON = 0.5;

bool showF = false; // true if -F is passed
bool showG = false; // true if -G is passed
bool showS = false; // true if -S is passed
bool out_flag = false;
bool gui_flag = false;
bool dist_flag = false;

// ===========================================================================
//  Trajectory-simplification geometry
// ===========================================================================

static constexpr double BMIN = -10000;
static constexpr double BMAX =  10000;
static constexpr double TOL  = 1e-6;

inline bool point_in_convex(const Point& p, const std::vector<Point>& poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto& a = poly[i];
        const auto& b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

inline std::optional<Point> ray_hit_bbox(const Point& p, const Point& dir) {
    double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    double dx = CGAL::to_double(dir.x()) - px,
           dy = CGAL::to_double(dir.y()) - py;
    double best = std::numeric_limits<double>::infinity(), hx = 0, hy = 0;
    auto consider = [&best, &hx, &hy, dx, dy, px, py](double t) {
        if (t <= 0) return;
        double x = px + t * dx, y = py + t * dy;
        if (x < BMIN - 1e-8 || x > BMAX + 1e-8 ||
            y < BMIN - 1e-8 || y > BMAX + 1e-8) return;
        if (t < best) { best = t; hx = x; hy = y; }
    };
    if (std::abs(dx) > 1e-18) {
        consider((BMIN - px) / dx);
        consider((BMAX - px) / dx);
    }
    if (std::abs(dy) > 1e-18) {
        consider((BMIN - py) / dy);
        consider((BMAX - py) / dy);
    }
    if (!std::isfinite(best)) return std::nullopt;
    return Point(hx, hy);
}

enum class Bbox_edge {
    BL = 0, BOTTOM = 1, BR = 2, RIGHT = 3,
    TR = 4, TOP = 5,    TL = 6, LEFT = 7
};

inline std::array<Point, 4> current_bbox_corner() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX), Point(BMIN, BMAX)};
}

inline std::vector<Point> current_bbox() {
    auto c = current_bbox_corner();
    return std::vector<Point>(c.begin(), c.end());
}

inline std::optional<Bbox_edge> which_edge(const Point& s) {
    double x = CGAL::to_double(s.x()), y = CGAL::to_double(s.y());
    bool on_left   = std::abs(x - BMIN) < TOL;
    bool on_right  = std::abs(x - BMAX) < TOL;
    bool on_bottom = std::abs(y - BMIN) < TOL;
    bool on_top    = std::abs(y - BMAX) < TOL;

    if (on_left && on_bottom) return Bbox_edge::BL;
    if (on_right && on_bottom) return Bbox_edge::BR;
    if (on_right && on_top) return Bbox_edge::TR;
    if (on_left && on_top) return Bbox_edge::TL;
    if (on_bottom) return Bbox_edge::BOTTOM;
    if (on_right)  return Bbox_edge::RIGHT;
    if (on_top)    return Bbox_edge::TOP;
    if (on_left)   return Bbox_edge::LEFT;
    return std::nullopt;
}

inline void append_rect_pts(std::vector<Point>& out, Bbox_edge from, Bbox_edge to, bool ccw) {
    auto corners = current_bbox_corner();
    auto next = [&](int idx) { return (idx + (ccw ? 1 : 7)) % 8; };

    int i = static_cast<int>(from);
    int j = static_cast<int>(to);
    if (i == j) return;
    for (int k = next(i); k != j; k = next(k)) {
        if ((k & 1) == 0) {
            int ci = k / 2;
            out.push_back(corners[ci]);
        }
    }
}

template <class F>
inline void for_each_grid_row(double px, double py, double r, double GRID, F&& f) {
    const double r2 = r * r;
    const int y_min = -(r / GRID) - 1;
    const int y_max = -y_min;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const double dy2 = y_actual * y_actual;
        if (dy2 > r2) continue;
        const double dx = std::sqrt(r2 - dy2);
        const int x_min = static_cast<int>(-dx / GRID - 1);
        const int x_max = static_cast<int>(+dx / GRID + 1);
        f(px, py, y_actual, x_min, x_max);
    }
}

inline double GRID_val(double EPSILON, double DELTA) {
    return EPSILON * DELTA / (2 * std::sqrt(2));
}

inline double R_val(double EPSILON, double DELTA) {
    return (1.0 + EPSILON / 2.0) * DELTA;
}

inline double& expected_frechet_ref() {
    static double value = 0;
    return value;
}

inline std::vector<Point> get_points_from_grid(const Point& p, double EPSILON, double DELTA) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val(EPSILON, DELTA);
    if (DELTA == 0) return std::vector<Point>{p};

    const double r = R_val(EPSILON, DELTA);
    const double r2 = r * r;
    const double r2_eps = r2 * (1.0 + 1e-9);

    const int j_min = static_cast<int>(std::floor(-r / GRID)) - 1;
    const int j_max = static_cast<int>(std::ceil(r / GRID)) + 1;
    const int k_min = j_min;
    const int k_max = j_max;

    auto cell_stabs = [&](int j, int k) -> bool {
        double cx = (j + 0.5) * GRID;
        double cy = (k + 0.5) * GRID;
        return (cx * cx + cy * cy) <= r2_eps;
    };

    std::vector<Point> points;
    for (int j = j_min; j <= j_max; ++j) {
        for (int k = k_min; k <= k_max; ++k) {
            if (cell_stabs(j-1, k-1) || cell_stabs(j, k-1) ||
                cell_stabs(j-1, k) || cell_stabs(j, k)) {
                Point corner(px + j * GRID, py + k * GRID);
                points.push_back(corner);
                expected_frechet_ref() = std::max(expected_frechet_ref(),
                    CGAL::to_double(CGAL::squared_distance(p, corner)));
            }
        }
    }
    return points;
}

inline std::vector<Point> get_conv_from_grid(const Point& p, double EPSILON, double DELTA) {
    std::vector<Point> points = get_points_from_grid(p, EPSILON, DELTA);
    std::vector<Point> conv;
    CGAL::convex_hull_2(points.begin(), points.end(), std::back_inserter(conv));
    return conv;
}

inline std::vector<int> find_tangent_idx(const Point& p, const std::vector<Point>& S) {
    int n = S.size();
    std::vector<int> tangent;
    tangent.reserve(2);

    auto orient_at = [&](int i) {
        return CGAL::orientation(p, S[i], S[(i + 1) % n]);
    };

    int prev = orient_at(n - 1);
    for (int i = 0; i < n; ++i) {
        int cur = orient_at(i);
        if (cur != prev && cur != CGAL::COLLINEAR) {
            tangent.push_back(i);
            if (tangent.size() == 2) break;
        }
        prev = cur;
    }
    return tangent;
}

inline std::optional<Point> intersect_ray_with_rect(const Point& p, const Point& direction) {
    if (CGAL::to_double(CGAL::squared_distance(p, direction)) < TOL * TOL)
        return std::nullopt;

    Ray ray(p, direction);
    Bbox box(BMIN, BMIN, BMAX, BMAX);

    if (auto obj = CGAL::intersection(Rect(box), ray)) {
        if (const Point* ip = std::get_if<Point>(&*obj)) {
            if (CGAL::to_double(CGAL::squared_distance(*ip, p)) < TOL * TOL)
                return std::nullopt;
            return *ip;
        }
        if (const Segment* seg = std::get_if<Segment>(&*obj)) {
            const Point& a = seg->source();
            const Point& b = seg->target();
            double da = CGAL::to_double(CGAL::squared_distance(a, p));
            double db = CGAL::to_double(CGAL::squared_distance(b, p));
            if (da < TOL * TOL) return b;
            if (db < TOL * TOL) return a;
            return (da < db) ? a : b;
        }
    }
    return std::nullopt;
}

inline std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    assert(S.size() != 2);
    if (S.size() == 1) return current_bbox();
    if (point_in_convex(p, S)) return current_bbox();

    std::vector<int> tangent = find_tangent_idx(p, S);
    assert(tangent.size() == 2);

    auto hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
    auto hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    if (!hit1 || !hit2) {
        std::cerr << "Ray doesn't intersect with bounding box!\n";
        return current_bbox();
    }

    auto e1 = which_edge(hit1.value());
    auto e2 = which_edge(hit2.value());

    int n = int(S.size());
    assert(n >= 3);
    CGAL_precondition(Polygon(S.begin(), S.end()).is_counterclockwise_oriented());
    assert(tangent[1] - tangent[0] - 1 >= 1 || tangent[0] + n - tangent[1] - 1 >= 1);

    std::vector<Point> F;
    if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]])) {
        std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1, std::back_inserter(F));
        F.push_back(hit2.value());
        append_rect_pts(F, e2.value(), e1.value(), true);
        F.push_back(hit1.value());
    } else {
        std::copy(S.begin() + tangent[1], S.end(), std::back_inserter(F));
        std::copy(S.begin(), S.begin() + tangent[0] + 1, std::back_inserter(F));
        F.push_back(hit1.value());
        append_rect_pts(F, e1.value(), e2.value(), true);
        F.push_back(hit2.value());
    }

    if (!e1 || !e2) {
        std::cerr << "Cannot determine which Bbox edge the ray intersect with.\n";
        return current_bbox();
    }
    return F;
}

