inline std::vector<Point> convex_intersect_fast(const std::vector<Point>& Pin,
                                                const std::vector<Point>& Qin) {
    if (Pin.size() < 3 || Qin.size() < 3) return {};

    // Cheap bbox-disjoint test: if axis-aligned bounding boxes are
    // separated, the two convex polygons cannot intersect. This avoids
    // the O(|P| + |Q|) cost of halfplane clipping when the result is
    // known empty.
    {
        double px_min = CGAL::to_double(Pin[0].x()), px_max = px_min;
        double py_min = CGAL::to_double(Pin[0].y()), py_max = py_min;
        for (size_t i = 1; i < Pin.size(); ++i) {
            double x = CGAL::to_double(Pin[i].x());
            double y = CGAL::to_double(Pin[i].y());
            if (x < px_min) px_min = x; else if (x > px_max) px_max = x;
            if (y < py_min) py_min = y; else if (y > py_max) py_max = y;
        }
        double qx_min = CGAL::to_double(Qin[0].x()), qx_max = qx_min;
        double qy_min = CGAL::to_double(Qin[0].y()), qy_max = qy_min;
        for (size_t i = 1; i < Qin.size(); ++i) {
            double x = CGAL::to_double(Qin[i].x());
            double y = CGAL::to_double(Qin[i].y());
            if (x < qx_min) qx_min = x; else if (x > qx_max) qx_max = x;
            if (y < qy_min) qy_min = y; else if (y > qy_max) qy_max = y;
        }
        if (px_max < qx_min || qx_max < px_min || py_max < qy_min || qy_max < py_min) {
            return {};
        }
    }

    auto signed_area_sign = [](const std::vector<Point>& P) {
        Epeck::FT s = 0;
        int sz = (int)P.size();
        for (int i = 0; i < sz; ++i) {
            Epeck::Point_2 a = conv_to_exact(P[i]);
            Epeck::Point_2 b = conv_to_exact(P[(i + 1) % sz]);
            s += a.x() * b.y() - b.x() * a.y();
        }
        return CGAL::sign(s);
    };

