inline std::optional<Point> line_intersect(const Point& a, const Point& b,
                                           const Point& p1, const Point& p2) {
    if (p1.x() == p2.x() && p1.y() == p2.y()) return p1;
    if (a.x() == b.x() && a.y() == b.y()) {
        return (CGAL::orientation(a, b, p1) != CGAL::RIGHT_TURN) ? std::optional<Point>(p1) : std::nullopt;
    }

    // Compute intersection in exact arithmetic (CGAL::sqrt-free cross-ratios
    // via FT::to_double would lose precision; we use the cartesian converter
    // path because the inputs are Epick FTs whose products stay exact in
    // Epeck). Reusing Epeck::Segment_2 + CGAL::intersection is the simplest
    // way to keep the resulting point exact and round-trip it back.
    Epeck::Point_2 ae = conv_to_exact(a);
    Epeck::Point_2 be = conv_to_exact(b);
    Epeck::Point_2 p1e = conv_to_exact(p1);
    Epeck::Point_2 p2e = conv_to_exact(p2);

    Epeck::Segment_2 seg_ab(ae, be);
    Epeck::Segment_2 seg_p(p1e, p2e);
    auto inter = CGAL::intersection(seg_ab, seg_p);
    if (!inter) return std::nullopt;
    if (const Epeck::Point_2* ip = std::get_if<Epeck::Point_2>(&*inter)) {
        return conv_to_inexact(*ip);
    }
    return std::nullopt;
}

