inline std::vector<Point> get_conv_from_grid(const Point& p, double EPSILON, double DELTA) {
    if (DELTA == 0) return std::vector<Point>{p};

    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double GRID = GRID_val(EPSILON, DELTA);
    const double r = R_val(EPSILON, DELTA);

    // Grid spans local coords [floor(-r/GRID)*GRID, ceil(r/GRID)*GRID] in each
    // axis. Its convex hull is the rectangle defined by those 4 corners.
    // This avoids the O(n log n) CGAL::convex_hull_2 call and the full
    // get_points_from_grid enumeration entirely.
    const double x_lo = px + std::floor(-r / GRID) * GRID;
    const double x_hi = px + std::ceil(r / GRID)  * GRID;
    const double y_lo = py + std::floor(-r / GRID) * GRID;
    const double y_hi = py + std::ceil(r / GRID)  * GRID;
    return {
        Point(x_lo, y_lo),
        Point(x_hi, y_lo),
        Point(x_hi, y_hi),
        Point(x_lo, y_hi),
    };
}

