// Fast vector-based intersect: writes the resulting polygon (vertices,
// CCW) to a vector<vector<Point>> output.  Caller uses S[i] = result[0].
// Skips is_simple()/is_clockwise_oriented() — we know the result is a
// convex polygon up to collinear/duplicate-vertex artefacts, and our
// post-filter strips those.
inline void intersect(const std::vector<Point>& P_verts, const std::vector<Point>& Q_verts,
                      std::back_insert_iterator<std::vector<std::vector<Point>>> result) {
    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back()) verts.pop_back();

    const int n = (int)verts.size();
    std::vector<Point> clean;
    clean.reserve(n);
    for (int i = 0; i < n; ++i) {
        const Point& cur = verts[i];
        if (!clean.empty() && clean.back() == cur) continue;
        const Point& prev = clean.empty() ? verts[(i - 1 + n) % n] : clean.back();
        const Point& next = verts[(i + 1) % n];
        if (CGAL::collinear(prev, cur, next)) continue;
        clean.push_back(cur);
    }
    if (clean.size() < 3) return;
    if (kernel_signed_area(clean) < 0) std::reverse(clean.begin(), clean.end());
    *result++ = std::move(clean);
}

