inline void intersect(const Polygon& subject, const Polygon& clip,
                      std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    std::vector<Point> P_verts, Q_verts;
    P_verts.reserve(subject.size());
    Q_verts.reserve(clip.size());
    for (auto it = subject.vertices_begin(); it != subject.vertices_end(); ++it) {
        P_verts.push_back(*it);
    }
    for (auto it = clip.vertices_begin(); it != clip.vertices_end(); ++it) {
        Q_verts.push_back(*it);
    }

    std::vector<Point> verts = orourke_cgal::convex_intersect(P_verts, Q_verts);
    if (verts.size() < 4) return;
    if (verts.front() == verts.back())
        verts.pop_back();

    // O'Rourke can emit collinear or duplicate vertices.  Strip them with an
    // O(n) post-filter (the intersection of two convex polygons is itself
    // convex, so we only need to filter kinks — no is_simple() / sweep
    // needed).  ~75% of the original intersect cost was is_simple().
    std::vector<Point> clean;
    clean.reserve(verts.size());
    const int n = (int)verts.size();
    for (int i = 0; i < n; ++i) {
        const Point& cur = verts[i];
        if (!clean.empty() && clean.back() == cur) continue;
        const Point& prev = clean.empty() ? verts[(i - 1 + n) % n] : clean.back();
        const Point& next = verts[(i + 1) % n];
        // Raw-double collinearity:  (cur - prev) x (next - prev) == 0
        const double x1 = CGAL::to_double(cur.x()) - CGAL::to_double(prev.x());
        const double y1 = CGAL::to_double(cur.y()) - CGAL::to_double(prev.y());
        const double x2 = CGAL::to_double(next.x()) - CGAL::to_double(prev.x());
        const double y2 = CGAL::to_double(next.y()) - CGAL::to_double(prev.y());
        if (x1 * y2 - y1 * x2 == 0.0) continue;
        clean.push_back(cur);
    }
    if (clean.size() < 3) return;

    Polygon inter_poly(clean.begin(), clean.end());
    if (inter_poly.is_clockwise_oriented()) inter_poly.reverse_orientation();
    *result++ = Polygon_with_holes(inter_poly);
}

