inline bool point_in_convex(const Point& p, const std::vector<Point>& poly, bool ccw = true) {
    // Raw-double orientation: our polygon vertices come from convex-hull
    // and grid constructions and are well separated from the edges, so we
    // don't need CGAL's exact-predicate filtering here.  Saves ~5x over
    // CGAL::orientation (which goes through an interval-arithmetic filter).
    const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    const size_t n = poly.size();
    for (size_t i = 0; i < n; ++i) {
        const double ax = CGAL::to_double(poly[i].x()),
                      ay = CGAL::to_double(poly[i].y());
        const double bx = CGAL::to_double(poly[(i + 1) % n].x()),
                      by = CGAL::to_double(poly[(i + 1) % n].y());
        const double det = (bx - ax) * (py - ay) - (by - ay) * (px - ax);
        if (ccw ? (det < 0) : (det > 0)) return false;
    }
    return true;
}

