    // Raw-double orientation.  Use orientation of (S[i], S[i+1], p):
    // negative (RIGHT_TURN) means p is to the right of edge (S[i], S[i+1]).
    const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    auto orient_at = [&](int i) -> int {
        const double ax = CGAL::to_double(S[i].x()),
                      ay = CGAL::to_double(S[i].y());
        const double bx = CGAL::to_double(S[(i + 1) % n].x()),
                      by = CGAL::to_double(S[(i + 1) % n].y());
        const double det = (bx - ax) * (py - ay) - (by - ay) * (px - ax);
        return (det > 0) - (det < 0);
